contract Lifebuoy {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev `keccak256(bytes("RescueTransferFailed()"))`.
    uint256 private constant _RESCUE_TRANSFER_FAILED_ERROR =
        0x1e4f60d2;

    /// @dev `keccak256(bytes("_RESCUE_LOCKED_FLAGS_SLOT"))`.
    uint256 internal constant _RESCUE_LOCKED_FLAGS_SLOT =
